import{z as o,x as l,o as A,c as d,q as r,j as n,D as t,d as e,s,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"高频 Beta","description":"","frontmatter":{"title":"高频 Beta","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hfs-highfreq-beta.md","filePath":"quant/hfs-highfreq-beta.md","lastUpdated":1791413859000}'),h={name:"quant/hfs-highfreq-beta.md"};function p(m,a,f,D,C,b){const B=l("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="高频-beta" tabindex="-1">高频 Beta <a class="header-anchor" href="#高频-beta" aria-label="Permalink to &quot;高频 Beta&quot;">​</a></h1><div class="epigraph"><p>beta 是协方差除以方差的高频版；两个估计量各自无偏，比值仍可以有偏——分母被噪声抬，分子被不同步压。</p><footer>—— 据 Barndorff-Nielsen and Shephard, Econometrica 2004；Andersen, Bollerslev, Diebold and Wu, 2006 整理</footer></div><p><a href="/quant/hfs-jump-detection">上一课</a>把跳拆成连续与瞬时两本账，单标的的读数齐了；对冲与风险要的是相对读数。日度定义在<a href="/quant/realized-beta">已实现 beta</a>写过，分子上的对齐问题在<a href="/quant/epps-effect">Epps 效应</a>与<a href="/quant/hayashi-yoshida">Hayashi–Yoshida 相关</a>写过；本课把三者合成一台机器：高频 beta 的三条偏差渠道、修正的组装方式，以及它与日频回归 beta 各自回答的问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>定义是比值：\\(\\hat\\beta_t=\\widehat{\\mathrm{RCov}}_t/\\widehat{\\mathrm{RV}}_t\\)，当日共同变差里这只股票对市场的暴露。它与三年日收益回归的平均斜率不是同一个量：前者是「这一天」的条件暴露，后者是长窗平均。Barndorff-Nielsen 与 Shephard（Econometrica 2004）给出无噪声同步下比值的渐近分布；Andersen、Bollerslev、Diebold 与 Wu（2006）证明它持续且可预报——所以有日用价值。缺口是三条偏差渠道都作用在比值上：不同步把分子压向零（Epps 机制），噪声把分母抬高，分子分母各自的估计误差在相除后放大。三条一起错，beta 可以缩水一半。</p><p><span class="marginnote">数例：分母被噪声抬高 20%、分子被不同步压低 30%，读数是 \\(0.7/1.2\\approx 0.58\\)——超过四成的暴露被系统性隐藏，对冲不足是常态而不是误差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>组装原则是<strong>同一家族、同一对齐</strong>。分子分母用同一族噪声修正估计量：多元核 beta（Barndorff-Nielsen、Hansen、Lunde 与 Shephard 的多元已实现核，2011），或 HY 型分子配同族核分母——两边的偏差各自消不掉，但同族处理使比值对共同的偏差模式不敏感。对齐方案先于估计量：刷新时间，或直接用<a href="/quant/hayashi-yoshida">Hayashi–Yoshida 相关</a>的相交增量做分子、同一时钟做分母。口径写死：日内 beta 通常不含隔夜收益，与含隔夜的日频 beta 差一截，比较时不可混。跳日单独标记：上一课的拆账在这里接上，\\(\\widehat{\\mathrm{RCov}}\\) 与 \\(\\widehat{\\mathrm{RV}}\\) 都取连续部分；跳日的 beta 是另一个条件量，不进同一条序列。</p><p><span class="marginnote">常见误区：「分子用先进的核，分母随便用朴素 RV 也行，反正都是方差。」量纲一样，但一个减了噪声、一个带着 \\(+2n\\sigma_\\varepsilon^2\\) 的虚肥，分母直接把 beta 压小，且偏差大小不可解释——比值的两端必须同一噪声处理。</span></p>',9)),(A(),n(i,null,{default:t(()=>[s(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AF%B9%E9%BD%90%EF%BC%9A%E5%88%B7%E6%96%B0%E6%97%B6%E9%97%B4%E6%88%96%20HY%20%E7%9B%B8%E4%BA%A4%E5%A2%9E%E9%87%8F%22%5D%20--%3E%20B%5B%22%E5%88%86%E5%AD%90%EF%BC%9A%E5%99%AA%E5%A3%B0%E7%A8%B3%E5%81%A5%20RCov%EF%BC%8C%E8%BF%9E%E7%BB%AD%E9%83%A8%E5%88%86%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%88%86%E6%AF%8D%EF%BC%9A%E5%90%8C%E6%97%8F%E5%99%AA%E5%A3%B0%E7%A8%B3%E5%81%A5%20RV%22%5D%0A%20%20B%20--%3E%20D%5B%22beta%20%3D%20RCov%20%2F%20RV%EF%BC%8C%E6%A0%87%E8%AE%B0%E8%B7%B3%E6%97%A5%22%5D%0A%20%20C%20--%3E%20D%0A%20%20D%20--%3E%20E%7B%22%E7%94%A8%E9%80%94%22%7D%0A%20%20E%20--%3E%7C%22%E7%9B%98%E4%B8%AD%E5%AF%B9%E5%86%B2%22%7C%20F%5B%22%E5%AF%B9%E5%86%B2%E6%AF%94%E5%9C%A8%E6%8C%81%E6%9C%89%E9%A2%91%E7%8E%87%E4%B8%8A%E5%AE%9A%E4%B9%89%22%5D%0A%20%20E%20--%3E%7C%22%E9%A3%8E%E9%99%A9%E5%88%86%E8%A7%A3%22%7C%20G%5B%22%E6%9D%A1%E4%BB%B6%E6%9A%B4%E9%9C%B2%E5%BA%8F%E5%88%97%EF%BC%8C%E6%8A%A5%E6%8C%81%E7%BB%AD%E6%80%A7%E4%B8%8E%E5%8F%AF%E9%A2%84%E6%8A%A5%E6%80%A7%22%5D%0A%20%20E%20--%3E%7C%22%E5%9B%A0%E5%AD%90%E7%9B%91%E6%8E%A7%22%7C%20H%5B%22%E4%B8%8E%E6%97%A5%E9%A2%91%20beta%20%E5%AF%B9%E7%85%A7%EF%BC%8C%E5%8F%A3%E5%BE%84%E5%88%86%E5%BC%80%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("比值放大偏差的机制在误差传播：\\(\\hat\\beta=\\hat c/\\hat v\\)，分子向下偏、分母向上偏时，读数按两者之和的幅度缩水——两条渠道"),E("strong",null,"同向"),e("，这是高频 beta 特别容易偏小的结构原因。流动性不对称是分子偏小的主渠道：慢腿的陈旧价把共同运动写成零收益格子，这与"),E("a",{href:"/quant/epps-effect"},"Epps 效应"),e("课里对冲比被压小、残差假平稳是同一机制。噪声渠道同样压小读数：它抬高的是分母。唯一常见的反向错误是噪声的交叉项进入分子——同一撮合事件同时污染两条腿时相关被高估——这要靠清洗与降噪处理，不靠降频掩盖。")],-1)),(A(),n(i,null,{default:t(()=>[s(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20AS%5B%22%E4%B8%8D%E5%90%8C%E6%AD%A5%3A%20%E6%85%A2%E8%85%BF%E9%99%88%E6%97%A7%E4%BB%B7%22%5D%20--%3E%20NUM%5B%22%E5%88%86%E5%AD%90%20RCov%20%E8%A2%AB%E5%8E%8B%E5%90%91%200%22%5D%0A%20%20NZ%5B%22%E5%BE%AE%E8%A7%82%E5%99%AA%E5%A3%B0%3A%20%E4%B9%B0%E5%8D%96%E5%BC%B9%E8%B7%B3%22%5D%20--%3E%20DEN%5B%22%E5%88%86%E6%AF%8D%20RV%20%E8%A2%AB%E6%8A%AC%E9%AB%98%22%5D%0A%20%20ERR%5B%22%E5%88%86%E5%AD%90%E5%88%86%E6%AF%8D%E5%90%84%E8%87%AA%E7%9A%84%E4%BC%B0%E8%AE%A1%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20AMP%5B%22%E7%9B%B8%E9%99%A4%E5%90%8E%E8%AF%AF%E5%B7%AE%E8%A2%AB%E6%94%BE%E5%A4%A7%22%5D%0A%20%20NUM%20--%3E%20RATIO%5B%22%CE%B2%CC%82%20%3D%20RCov%20%2F%20RV%22%5D%0A%20%20DEN%20--%3E%20RATIO%0A%20%20AMP%20--%3E%20RATIO%0A%20%20RATIO%20--%3E%20SMALL%5B%22%E8%AF%BB%E6%95%B0%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E5%B0%8F%3A%20%E5%AF%B9%E5%86%B2%E4%B8%8D%E8%B6%B3%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">直觉类比：beta 像「天线增益比」——分子是接到了多少共同信号，分母是自己有多大嗓门。噪声把嗓门吹大、不同步把信号调小，读出来的接收能力就假性变差，而真实接收能力没变。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>高频 beta 回答「今天的共同波动」，不回答贝塔是否是稳定参数：后者要用它自己的时序与日频证据对照。极端行情里市场本身在跳，连续部分的比值可能不再是想要的暴露定义，跳日的账单独看。大截面（几百只对同一市场组合）逐只算比值与一次估整块协方差不是一回事——整块的路径是下一课。最后，可预报性（Andersen 等，2006）是统计性质，把它当可交易信号之前，先过容量与换手。</p><p><span class="marginnote">为什么偏小要紧：用被压小的 beta 算对冲头寸，对冲腿会系统性开不够，残余风险专门在市场大跌的日子暴露——恰恰是最需要对冲的时刻。做风险分解时同理，低 beta 组合的「低暴露」有一部分可能只是测量假象。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定义在条件口径上：\\(\\widehat{\\mathrm{RCov}}/\\widehat{\\mathrm{RV}}\\) 是「这一天」的暴露，不是三年回归的平均斜率。</li><li>三条偏差渠道同向压小读数：异步压分子、噪声抬分母、误差在比值里放大。</li><li>组装原则：同族估计量、同一对齐时钟、连续部分口径、跳日单独标记。</li><li>与日频 beta 不可互换：含不含隔夜、条件与平均，回答不同的风险问题。</li><li>出处：Barndorff-Nielsen and Shephard, <em>Econometrica</em>, 2004；Andersen, Bollerslev, Diebold and Wu, <em>Realized Beta: Persistence and Predictability</em>, 2006；多元核见 Barndorff-Nielsen, Hansen, Lunde and Shephard, <em>Journal of Econometrics</em>, 2011。</li></ul>',6))])}const F=o(h,[["render",p]]);export{c as __pageData,F as default};
